"""Vector drawing primitives for a tag sheet in millimetre coordinates.

Layout math is done top-down (matching page reading order); PDF output uses a
bottom-left origin, so every y coordinate is flipped exactly once here.
"""

from dataclasses import dataclass
from typing import Literal

from beartype import beartype

from arm_observer.apriltag.families import TagFamily
from arm_observer.apriltag.layout import SheetPlan, TagSlot

Fill = Literal["black", "white"]
Anchor = Literal["left", "center", "right"]

LABEL_FONT_SIZE_PT = 6.5
HEADER_FONT_SIZE_PT = 11.0
SUBHEADER_FONT_SIZE_PT = 8.0
FOOTER_FONT_SIZE_PT = 7.0
LABEL_GAP_MM = 3.0
HEADER_BASELINES_MM = (5.5, 11.0)
TICK_HEIGHT_MM = 2.5
TICK_LINE_WIDTH_MM = 0.3


@beartype
@dataclass(frozen=True, slots=True)
class RectOp:
    x_mm: float
    y_mm: float
    width_mm: float
    height_mm: float
    fill: Fill


@beartype
@dataclass(frozen=True, slots=True)
class LineOp:
    x1_mm: float
    y1_mm: float
    x2_mm: float
    y2_mm: float
    width_mm: float


@beartype
@dataclass(frozen=True, slots=True)
class TextOp:
    x_mm: float
    y_mm: float
    text: str
    size_pt: float
    anchor: Anchor


@beartype
@dataclass(frozen=True, slots=True)
class Drawing:
    page_width_mm: float
    page_height_mm: float
    ops: tuple[RectOp | LineOp | TextOp, ...]

    @property
    def rects(self) -> tuple[RectOp, ...]:
        return tuple(op for op in self.ops if isinstance(op, RectOp))

    @property
    def lines(self) -> tuple[LineOp, ...]:
        return tuple(op for op in self.ops if isinstance(op, LineOp))

    @property
    def texts(self) -> tuple[TextOp, ...]:
        return tuple(op for op in self.ops if isinstance(op, TextOp))


def _flip(page_height_mm: float, y_top_mm: float, height_mm: float) -> float:
    return page_height_mm - y_top_mm - height_mm


@beartype
def _header_ops(plan: SheetPlan, family: TagFamily) -> list[TextOp]:
    spec = plan.spec
    grid_top = min(slot.y_mm for slot in plan.slots)
    top = grid_top - spec.header_mm
    first, last = min(plan.tag_ids), max(plan.tag_ids)
    center_x = spec.page.width_mm / 2
    title = f"AprilTag {family.name} - A4 tag sheet {plan.sheet_index}/{plan.sheet_count}"
    subtitle = (
        f"tag {spec.tag_size_mm:g} mm | gap {spec.gap_mm:g} mm | IDs {first}-{last} | "
        "PRINT AT 100% (ACTUAL SIZE)"
    )
    return [
        TextOp(center_x, _flip(spec.page.height_mm, top + HEADER_BASELINES_MM[0], 0.0),
               title, HEADER_FONT_SIZE_PT, "center"),
        TextOp(center_x, _flip(spec.page.height_mm, top + HEADER_BASELINES_MM[1], 0.0),
               subtitle, SUBHEADER_FONT_SIZE_PT, "center"),
    ]


@beartype
def _tag_ops(slot: TagSlot, family: TagFamily, page_height_mm: float) -> list[RectOp]:
    cell = slot.size_mm / family.module_side
    ops = []
    for row, line in enumerate(family.tag_modules(slot.tag_id)):
        for column, black in enumerate(line):
            if black:
                ops.append(
                    RectOp(
                        slot.x_mm + column * cell,
                        _flip(page_height_mm, slot.y_mm + row * cell, cell),
                        cell,
                        cell,
                        "black",
                    )
                )
    return ops


@beartype
def _label_ops(slot: TagSlot, page_height_mm: float) -> list[TextOp]:
    baseline = slot.y_mm + slot.size_mm + LABEL_GAP_MM
    return [
        TextOp(
            slot.x_mm + slot.size_mm / 2,
            _flip(page_height_mm, baseline, 0.0),
            f"ID {slot.tag_id}",
            LABEL_FONT_SIZE_PT,
            "center",
        )
    ]


@beartype
def _reference_ops(plan: SheetPlan, page_height_mm: float) -> list[RectOp | LineOp | TextOp]:
    bar = plan.reference_bar
    page_width = plan.spec.page.width_mm
    ops: list[RectOp | LineOp | TextOp] = [
        RectOp(bar.x_mm, _flip(page_height_mm, bar.y_mm, bar.height_mm), bar.length_mm,
               bar.height_mm, "black")
    ]
    tick_count = int(round(bar.length_mm / bar.tick_spacing_mm))
    tick_y1 = _flip(page_height_mm, bar.y_mm - TICK_HEIGHT_MM, 0.0)
    tick_y2 = _flip(page_height_mm, bar.y_mm, 0.0)
    for index in range(tick_count + 1):
        x = bar.x_mm + index * bar.tick_spacing_mm
        ops.append(LineOp(x, tick_y1, x, tick_y2, TICK_LINE_WIDTH_MM))
    label_y = _flip(page_height_mm, bar.y_mm - TICK_HEIGHT_MM - 1.0, 0.0)
    ops.append(TextOp(bar.x_mm, label_y, "0", FOOTER_FONT_SIZE_PT, "left"))
    ops.append(
        TextOp(bar.x_mm + bar.length_mm, label_y, f"{bar.length_mm:g} mm", FOOTER_FONT_SIZE_PT,
               "right")
    )
    ops.append(
        TextOp(
            page_width / 2,
            _flip(page_height_mm, bar.y_mm + bar.height_mm + 4.0, 0.0),
            "Measure the 100 mm reference bar; if it is not exactly 100 mm, disable printer "
            "scaling.",
            FOOTER_FONT_SIZE_PT,
            "center",
        )
    )
    return ops


@beartype
def build_sheet_drawing(plan: SheetPlan, family: TagFamily) -> Drawing:
    page = plan.spec.page
    ops: list[RectOp | LineOp | TextOp] = list(_header_ops(plan, family))
    for slot in plan.slots:
        ops.extend(_tag_ops(slot, family, page.height_mm))
        ops.extend(_label_ops(slot, page.height_mm))
    ops.extend(_reference_ops(plan, page.height_mm))
    return Drawing(page.width_mm, page.height_mm, tuple(ops))

"""Actual-size A4 PDF output for tag sheet plans."""

from pathlib import Path

from beartype import beartype
from reportlab.lib.units import mm as POINTS_PER_MM
from reportlab.pdfgen.canvas import Canvas

from arm_observer.apriltag.drawing import Drawing, LineOp, RectOp, TextOp, build_sheet_drawing
from arm_observer.apriltag.families import TagFamily
from arm_observer.apriltag.layout import SheetPlan

BLACK = (0.0, 0.0, 0.0)
WHITE = (1.0, 1.0, 1.0)
TEXT_FONT = "Helvetica"


@beartype
def sheet_filename(plan: SheetPlan, family: TagFamily) -> str:
    short_name = family.name.removeprefix("tag")
    first, last = min(plan.tag_ids), max(plan.tag_ids)
    return (
        f"apriltag_{short_name}_a4_sheet_{plan.sheet_index}_ids_{first:03d}-{last:03d}.pdf"
    )


@beartype
def _draw_rect(canvas: Canvas, op: RectOp) -> None:
    canvas.setFillColorRGB(*(BLACK if op.fill == "black" else WHITE))
    canvas.rect(
        op.x_mm * POINTS_PER_MM,
        op.y_mm * POINTS_PER_MM,
        op.width_mm * POINTS_PER_MM,
        op.height_mm * POINTS_PER_MM,
        stroke=0,
        fill=1,
    )


@beartype
def _draw_line(canvas: Canvas, op: LineOp) -> None:
    canvas.setStrokeColorRGB(*BLACK)
    canvas.setLineWidth(op.width_mm * POINTS_PER_MM)
    canvas.line(
        op.x1_mm * POINTS_PER_MM,
        op.y1_mm * POINTS_PER_MM,
        op.x2_mm * POINTS_PER_MM,
        op.y2_mm * POINTS_PER_MM,
    )


@beartype
def _draw_text(canvas: Canvas, op: TextOp) -> None:
    canvas.setFillColorRGB(*BLACK)
    canvas.setFont(TEXT_FONT, op.size_pt)
    position = (op.x_mm * POINTS_PER_MM, op.y_mm * POINTS_PER_MM)
    if op.anchor == "center":
        canvas.drawCentredString(*position, op.text)
    elif op.anchor == "right":
        canvas.drawRightString(*position, op.text)
    else:
        canvas.drawString(*position, op.text)


@beartype
def _write_drawing(canvas: Canvas, drawing: Drawing) -> None:
    for op in drawing.ops:
        if isinstance(op, RectOp):
            _draw_rect(canvas, op)
        elif isinstance(op, LineOp):
            _draw_line(canvas, op)
        else:
            _draw_text(canvas, op)


@beartype
def write_sheet_pdf(plan: SheetPlan, family: TagFamily, path: Path) -> Path:
    drawing = build_sheet_drawing(plan, family)
    path.parent.mkdir(parents=True, exist_ok=True)
    page = plan.spec.page
    canvas = Canvas(
        str(path),
        pagesize=(page.width_mm * POINTS_PER_MM, page.height_mm * POINTS_PER_MM),
        pageCompression=1,
    )
    _write_drawing(canvas, drawing)
    canvas.showPage()
    canvas.save()
    return path

"""Synthetic captures of tag sheets with known ground-truth corners."""

from dataclasses import dataclass

import cv2
import numpy as np
from beartype import beartype

from arm_observer.apriltag.detector import Detection
from arm_observer.apriltag.families import TagFamily
from arm_observer.apriltag.layout import SheetPlan

DEFAULT_PX_PER_MM = 6.0
QUIET_CELLS = 1


@beartype
@dataclass(frozen=True, slots=True)
class SceneTruth:
    tag_id: int
    corners_px: tuple[tuple[float, float], ...]


@beartype
@dataclass(frozen=True, slots=True)
class SyntheticScene:
    image: np.ndarray
    truths: tuple[SceneTruth, ...]
    px_per_mm: float


@beartype
def render_tag_image(
    family: TagFamily, tag_id: int, cell_px: int, quiet_cells: int = QUIET_CELLS
) -> np.ndarray:
    if cell_px <= 0 or quiet_cells < 0:
        raise ValueError("cell_px must be positive and quiet_cells nonnegative")
    modules = family.tag_modules(tag_id)
    side = family.module_side + 2 * quiet_cells
    image = np.full((side * cell_px, side * cell_px), 255, dtype=np.uint8)
    for row, line in enumerate(modules):
        for column, black in enumerate(line):
            if black:
                top = (row + quiet_cells) * cell_px
                left = (column + quiet_cells) * cell_px
                image[top : top + cell_px, left : left + cell_px] = 0
    return image


@beartype
def _sheet_plane(plan: SheetPlan, family: TagFamily, px_per_mm: float) -> np.ndarray:
    page = plan.spec.page
    height = int(round(page.height_mm * px_per_mm))
    width = int(round(page.width_mm * px_per_mm))
    plane = np.full((height, width), 255, dtype=np.uint8)
    cell_mm = plan.spec.tag_size_mm / family.module_side
    cell_px = int(round(cell_mm * px_per_mm))
    for slot in plan.slots:
        for row, line in enumerate(family.tag_modules(slot.tag_id)):
            for column, black in enumerate(line):
                if black:
                    top = int(round((slot.y_mm + row * cell_mm) * px_per_mm))
                    left = int(round((slot.x_mm + column * cell_mm) * px_per_mm))
                    plane[top : top + cell_px, left : left + cell_px] = 0
    return plane


def _default_perspective(width: int, height: int) -> tuple[np.ndarray, np.ndarray]:
    source = np.array([[0, 0], [width, 0], [width, height], [0, height]], dtype=np.float32)
    destination = np.array(
        [
            [0.07 * width, 0.05 * height],
            [0.94 * width, 0.09 * height],
            [0.97 * width, 0.95 * height],
            [0.03 * width, 0.91 * height],
        ],
        dtype=np.float32,
    )
    return source, destination


@beartype
def _warp(plane: np.ndarray, perspective: bool) -> tuple[np.ndarray, np.ndarray]:
    height, width = plane.shape
    if not perspective:
        return plane.copy(), np.eye(3, dtype=np.float64)
    source, destination = _default_perspective(width, height)
    matrix = cv2.getPerspectiveTransform(source, destination)
    warped = cv2.warpPerspective(
        plane, matrix, (width, height), flags=cv2.INTER_LINEAR, borderValue=255
    )
    return warped, matrix


@beartype
def _truth(plan: SheetPlan, px_per_mm: float, matrix: np.ndarray) -> tuple[SceneTruth, ...]:
    truths = []
    for slot in plan.slots:
        corners = np.array(
            [
                [slot.x_mm, slot.y_mm],
                [slot.x_mm + slot.size_mm, slot.y_mm],
                [slot.x_mm + slot.size_mm, slot.y_mm + slot.size_mm],
                [slot.x_mm, slot.y_mm + slot.size_mm],
            ],
            dtype=np.float64,
        ) * px_per_mm
        transformed = cv2.perspectiveTransform(
            corners.reshape(-1, 1, 2), matrix
        ).reshape(-1, 2)
        truths.append(
            SceneTruth(slot.tag_id, tuple((float(x), float(y)) for x, y in transformed))
        )
    return tuple(truths)


@beartype
def _degrade(image: np.ndarray, blur_sigma: float, noise_sigma: float, seed: int) -> np.ndarray:
    result = image.astype(np.float32)
    if blur_sigma > 0:
        result = cv2.GaussianBlur(result, (0, 0), blur_sigma)
    if noise_sigma > 0:
        result = result + np.random.default_rng(seed).normal(0.0, noise_sigma, result.shape)
    return np.clip(result, 0, 255).astype(np.uint8)


@beartype
def render_sheet_scene(
    plan: SheetPlan,
    family: TagFamily,
    *,
    px_per_mm: float = DEFAULT_PX_PER_MM,
    perspective: bool = True,
    blur_sigma: float = 0.0,
    noise_sigma: float = 0.0,
    seed: int = 0,
) -> SyntheticScene:
    if px_per_mm <= 0:
        raise ValueError("px_per_mm must be positive")
    plane = _sheet_plane(plan, family, px_per_mm)
    warped, matrix = _warp(plane, perspective)
    image = _degrade(warped, blur_sigma, noise_sigma, seed)
    return SyntheticScene(image, _truth(plan, px_per_mm, matrix), px_per_mm)


@beartype
def corner_rms_px(detection: Detection, truth: tuple[tuple[float, float], ...]) -> float:
    detected = np.asarray(detection.corners, dtype=np.float64)
    expected = np.asarray(truth, dtype=np.float64)
    if detected.shape != expected.shape:
        raise ValueError("detection and truth must have the same corner shape")
    errors = [
        float(np.sqrt(np.mean(np.sum((detected - np.roll(expected, shift, axis=0)) ** 2, axis=1))))
        for shift in range(len(expected))
    ]
    return min(errors)

